import type {
  ServiceWorkerMessageRequest,
  ServiceWorkerMessageResponse,
  ServiceWorkerPreloadedQuery,
} from '@github-ui/service-worker-connector/sw-types'
import {STALE_OFFSET_MS} from './sw-constants'
import {
  parseInterceptableUrl,
  swCache,
  reportError,
  generateCacheKeysForParams,
  getQueryNameForParams,
} from './sw-utils'
import {
  SW_MSG_CACHED_QUERIES_RESPONSE,
  SW_MSG_GET_CACHED_QUERIES,
} from '@github-ui/service-worker-connector/sw-constants'

export type PersistedQuery = {
  queryHash?: string
  queryKey?: readonly unknown[]
  variables?: Record<string, unknown>
  state: {
    data: {
      data: unknown
    }
    dataUpdatedAt: number
  }
}

const buildPreloadedQueryPayload = (cachedData: PersistedQuery, queryName: string): ServiceWorkerPreloadedQuery => ({
  queryId: cachedData.queryHash ?? '',
  queryName,
  variables: cachedData.variables ?? {},
  result: {data: cachedData.state.data.data},
  timestamp: Math.floor(cachedData.state.dataUpdatedAt / 1000) - STALE_OFFSET_MS / 1000,
  injectedByServiceWorker: true,
})

export function replyToPort(event: ExtendableMessageEvent, response: ServiceWorkerMessageResponse): void {
  event.ports[0]?.postMessage(response)
}

const notFoundResponse: ServiceWorkerMessageResponse = {
  type: SW_MSG_CACHED_QUERIES_RESPONSE,
  success: false,
  reason: 'not_found',
  data: null,
}

const errorResponse: ServiceWorkerMessageResponse = {
  type: SW_MSG_CACHED_QUERIES_RESPONSE,
  success: false,
  reason: 'error',
  data: null,
}

export const handleMessage = (event: ExtendableMessageEvent) => {
  try {
    const message = event.data as ServiceWorkerMessageRequest
    if (message?.type !== SW_MSG_GET_CACHED_QUERIES || !message.url) {
      reportError(new Error(`Unexpected message type: ${message?.type}`))
      return
    }
    const pageParams = parseInterceptableUrl(message.url)
    if (!pageParams) {
      reportError(new Error(`Could not parse page params from URL: ${message.url}`))
      replyToPort(event, notFoundResponse)
      return
    }

    const queryName = getQueryNameForParams(pageParams)
    const candidateKeys = generateCacheKeysForParams(pageParams)
    let cachedData: PersistedQuery | undefined

    for (const candidateKey of candidateKeys) {
      cachedData = swCache.get(candidateKey) as PersistedQuery | undefined
      if (cachedData) break
    }

    if (cachedData) {
      replyToPort(event, {
        type: SW_MSG_CACHED_QUERIES_RESPONSE,
        success: true,
        data: {preloadedQueries: [buildPreloadedQueryPayload(cachedData, queryName)]},
      })
    } else {
      replyToPort(event, notFoundResponse)
    }
  } catch (error) {
    reportError(error)
    replyToPort(event, errorResponse)
  }
}
