import type {SendAnalyticsEventFunction} from '@github-ui/safe-indexed-db-storage'

export type Context = Record<string, string>

export interface AnalyticsClientOptions {
  collectorUrl: string
  baseContext?: Context
}

interface EventPayload {
  type: string
  context?: Context
}

interface ApiPayload {
  events?: EventPayload[]
}

/**
 * A simple analytics client designed for service worker contexts.
 * Unlike the browser version, this doesn't rely on `document`, `location`,
 * or `navigator.sendBeacon` which are unavailable in service workers.
 */
export class AnalyticsClient {
  readonly options: AnalyticsClientOptions

  constructor(options: AnalyticsClientOptions) {
    this.options = options
  }

  get collectorUrl() {
    return this.options.collectorUrl
  }

  #createEvent(type: string, context?: Context): EventPayload {
    return {
      type,
      context: {
        ...this.options.baseContext,
        ...context,
      },
    }
  }

  sendEvent(type: string, context?: Context) {
    const event = this.#createEvent(type, context)
    this.#send({events: [event]})
  }

  async #send({events}: {events?: EventPayload[]}) {
    const payload: ApiPayload = {
      events,
    }
    const body = JSON.stringify(payload)

    // In service workers, we only have fetch available (no sendBeacon)
    try {
      await fetch(this.collectorUrl, {
        method: 'POST',
        cache: 'no-cache',
        headers: {
          'Content-Type': 'application/json',
        },
        body,
        keepalive: true,
      })
    } catch {
      // Silently ignore fetch errors in service worker analytics
    }
  }
}

export type ServiceWorkerAnalyticsConfig = {
  collectorUrl: string
  actorLogin: string
  release?: string
  actorId?: string
}

let analyticsClient: AnalyticsClient | undefined
let baseContext: Context = {}

export function initServiceWorkerAnalytics(config: ServiceWorkerAnalyticsConfig) {
  if (analyticsClient) {
    return
  }
  if (!config.collectorUrl) {
    return
  }

  try {
    analyticsClient = new AnalyticsClient({
      collectorUrl: config.collectorUrl,
    })

    baseContext = {
      actor_login: config.actorLogin,
      service_worker: 'true',
    }

    if (config.release) {
      baseContext.release = config.release
    }
    if (config.actorId) {
      baseContext.actor_id = config.actorId
    }
  } catch {
    // Failed to initialize analytics - analytics are likely disabled
  }
}

export const sendAnalyticsEvent: SendAnalyticsEventFunction = (eventType, target, payload = {}) => {
  if (!analyticsClient) {
    return
  }

  // Capture the client reference before the microtask
  const client = analyticsClient

  // Fire and forget - don't block the main execution
  queueMicrotask(() => {
    const context: Context = {
      ...baseContext,
    }

    if (target) {
      context.target = target
    }

    // Convert all payload values to strings (matching hydro-analytics behavior)
    for (const [key, value] of Object.entries(payload)) {
      if (value !== undefined && value !== null) {
        context[key] = `${value}`
      }
    }

    const typeWithFallback = eventType || 'unknown'
    client.sendEvent(typeWithFallback, context)
  })
}
