import {setClientEnvForSsr} from '@github-ui/client-env'
import {createSafeIndexedDbPersister, SIMPLE_VALIDATOR} from '@github-ui/safe-indexed-db-storage'
import {initServiceWorkerAnalytics, sendAnalyticsEvent} from './service-worker-analytics'
import {initServiceWorkerFailbot} from './service-worker-failbot'
import {handleMessage, type PersistedQuery} from './sw-message-handler'
import {SERVICE_WORKER_VERSION, SERVICE_WORKER_EVENTS, PRE_FETCH_TIMEOUT_MS} from './sw-constants'
import {
  reportError,
  swCache,
  parseInterceptableUrl,
  generateCacheKeysForParams,
  getRelease,
  getActorId,
  getStorage,
  setCurrentUser,
  setRelease,
  setActorId,
  setStorage,
  getCurrentUser,
  type InterceptablePageParams,
} from './sw-utils'

// eslint-disable-next-line ssr-friendly/no-dom-globals-in-module-scope
const serviceWorker = self as unknown as ServiceWorkerGlobalScope

export const handleInstall = (sw: ServiceWorkerGlobalScope = serviceWorker) => {
  sw.skipWaiting()
}

export const handleActivate = (sw: ServiceWorkerGlobalScope = serviceWorker) => {
  sw.clients.claim()
}

type WithTimeoutResult<T> = {
  result: T | undefined
  timedOut: boolean
}

const withTimeout = async <T>(promise: Promise<T>, timeoutMs: number): Promise<WithTimeoutResult<T>> => {
  let timeoutId: ReturnType<typeof setTimeout> | undefined
  let didTimeout = false

  const timeoutPromise = new Promise<undefined>(resolve => {
    timeoutId = setTimeout(() => {
      didTimeout = true
      resolve(undefined)
    }, timeoutMs)
  })

  try {
    const result = await Promise.race([promise, timeoutPromise])
    if (timeoutId) clearTimeout(timeoutId)
    return {result, timedOut: didTimeout}
  } catch (error) {
    if (timeoutId) clearTimeout(timeoutId)
    throw error
  }
}

type PreFetchResult = {
  cachedData: PersistedQuery | undefined
  cacheKey: string
  hasCachedResult: boolean
  durationMs: number
}

const preFetchCacheLookup = async (candidateKeys: string[]): Promise<PreFetchResult> => {
  const startTime = performance.now()

  const currentStorage = getStorage()
  let cachedData: PersistedQuery | undefined
  let cacheKey = candidateKeys[0] ?? ''

  if (currentStorage) {
    const lookups = candidateKeys.map(async key => {
      const data = await currentStorage.getItem(key)
      return {data: data as PersistedQuery | undefined, key}
    })

    const results = await Promise.all(lookups)
    for (const result of results) {
      if (result.data) {
        cachedData = result.data
        cacheKey = result.key
        break
      }
    }
  }

  const endTime = performance.now()
  return {
    cachedData,
    cacheKey,
    hasCachedResult: cachedData !== undefined,
    durationMs: Math.round(endTime - startTime),
  }
}

const handleInterceptedRequest = async (
  event: FetchEvent,
  candidateKeys: string[],
  navType: 'hard' | 'turbo',
  page: InterceptablePageParams['type'],
): Promise<Response> => {
  const targetUrl = event.request.url
  const referrer = event.request.referrer || undefined
  const defaultCacheKey = candidateKeys[0] ?? ''

  try {
    const {result: preFetchResult, timedOut: preFetchTimedOut} = await withTimeout(
      preFetchCacheLookup(candidateKeys),
      PRE_FETCH_TIMEOUT_MS,
    )

    const hasCachedResult = preFetchResult?.hasCachedResult ?? false
    const cachedData = preFetchResult?.cachedData
    const queryHash = cachedData?.queryHash ?? 'unknown'
    const actualCacheKey = preFetchResult?.cacheKey ?? defaultCacheKey
    const preFetchDurationMs = preFetchResult?.durationMs ?? PRE_FETCH_TIMEOUT_MS

    if (preFetchTimedOut) {
      reportError(new Error('pre_fetch_cache_lookup_timeout'), {targetUrl, referrer, navType})
    }

    const newHeaders = new Headers(event.request.headers)
    if (hasCachedResult) {
      newHeaders.set('X-Issues-React-Relay-Cache', `${page}:${queryHash}`)
    }

    const modifiedRequest = new Request(event.request, {
      headers: newHeaders,
    })

    sendAnalyticsEvent(SERVICE_WORKER_EVENTS.PREREQUEST, actualCacheKey, {
      duration_ms: preFetchDurationMs,
      cache_hit: hasCachedResult,
      service_worker_version: SERVICE_WORKER_VERSION,
      target_url: targetUrl,
      referrer,
      nav_type: navType,
    })

    // Store cached data in the in-memory LRU cache for later retrieval via postMessage
    if (hasCachedResult && cachedData) {
      swCache.set(actualCacheKey, cachedData)
    }

    return fetch(modifiedRequest)
  } catch (error) {
    reportError(error, {targetUrl, referrer, navType})
    return fetch(event.request)
  }
}

export const handleFetch = (event: FetchEvent, sw: ServiceWorkerGlobalScope = serviceWorker) => {
  try {
    // Only intercept GET requests
    if (event.request.method !== 'GET') return
    if (!getCurrentUser()) {
      const url = new URL(sw.location.href, sw.location.origin)
      const errorsUrl = url.searchParams.get('errors_url')
      setCurrentUser(url.searchParams.get('current_user'))
      setRelease(url.searchParams.get('release'))
      setActorId(url.searchParams.get('actor_id'))
      if (errorsUrl) {
        initServiceWorkerFailbot({
          errorsUrl,
          user: getCurrentUser() || undefined,
          catalogService: 'github/issues',
          release: getRelease() || undefined,
          actorId: getActorId() || undefined,
        })
      }
      const user = getCurrentUser()
      if (!user) {
        // Unregister the service worker if we don't have a current user this should not happen in practice
        reportError(new Error(`[${SERVICE_WORKER_VERSION}] missing_current_user in handleFetch`))
        sw.registration.unregister()
        return
      }
      setClientEnvForSsr({locale: 'en-US', featureFlags: [], copilotApiOverrideUrl: undefined, login: user})
      const analyticsCollectorUrl = url.searchParams.get('analytics_collector_url')
      if (analyticsCollectorUrl) {
        initServiceWorkerAnalytics({
          collectorUrl: analyticsCollectorUrl,
          actorLogin: user,
          release: getRelease() || undefined,
          actorId: getActorId() || undefined,
        })
      }
    }

    const pageParams = parseInterceptableUrl(event.request.url)
    if (!pageParams || !getCurrentUser()) return

    if (!getStorage()) {
      setStorage(
        createSafeIndexedDbPersister({
          validator: SIMPLE_VALIDATOR,
          sendAnalyticsEvent,
        }),
      )
    }

    const turboVisit = event.request.headers.get('Turbo-Visit')
    const turboFrame = event.request.headers.get('Turbo-Frame')
    const isTurboRequest = Boolean(turboVisit || turboFrame)
    const navType: 'hard' | 'turbo' = isTurboRequest ? 'turbo' : 'hard'

    const shouldIntercept = event.request.mode === 'navigate' || isTurboRequest
    if (shouldIntercept) {
      const candidateKeys = generateCacheKeysForParams(pageParams)
      event.respondWith(handleInterceptedRequest(event, candidateKeys, navType, pageParams.type))
    }
  } catch (error) {
    const targetUrl = event.request.url
    const referrer = event.request.referrer || undefined
    reportError(error, {targetUrl, referrer})
  }
}

serviceWorker.addEventListener('install', () => handleInstall())
serviceWorker.addEventListener('activate', () => handleActivate())
serviceWorker.addEventListener('fetch', handleFetch)
serviceWorker.addEventListener('message', handleMessage)
